            }
            else
            {
                load = K(-0.55f).Sp(6f, -45f, 0f).Ch(4f, -25f, 0f).Hd(0f, 35f, 0f).RA(-50f, 0f, -60f).RF(-70f, 0f, 0f).LA(-40f, 0f, 25f).LF(-50f, 0f, 0f).Off(0f, -0.06f, 0f).LL(0.2f, 0.08f, 0.25f, 0f).RL(0.05f, 0.08f, 0.3f, 0f);
