        public static string PairedCarrier(Animator a)
        {
            string[] candidates = { "swing_axe", "axe_swing" };
            for (int i = 0; i < candidates.Length; i++) if (StrictTriggerCount(a, candidates[i]) >= 3) return candidates[i];
